require_once __DIR__.'/../includes/support.php';
$staffView=isset($staffView)&&$staffView;
if ($staffView) requireStaff();
$base=$staffView?'/admin/support':'/support';

$selected=filter_var($_GET['ticket']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);
if($selected===false){flash('error','Conversa indisponível.');redirect($base);} $ticket=null; $messages=[];
if ($selected) {
    try { $ticket=supportTicket($pdo,$selected,(int)userId(),$staffView); $messages=supportMessages($pdo,$selected,(int)userId(),$staffView); }
    catch (RuntimeException $e) { flash('error','Conversa indisponível.'); redirect($base); }
}
$summary=supportSummary($pdo,(int)userId(),$staffView);
