$ticketUrl=static fn($id)=>$base.'?'.http_build_query($filters+['ticket'=>$id]);
$closed=$ticket&&in_array($ticket['status'],['resolved','closed'],true);
$recent=$pdo->prepare('SELECT m.id,m.match_code FROM matches m JOIN match_players mp ON mp.match_id=m.id WHERE mp.player_id=? ORDER BY m.id DESC LIMIT 20');
